## ---- 01: CPR ⇄ SMM Conversions  (qmd line 238) ---------------------------------------

cpr_to_smm <- function(cpr) 1 - (1 - cpr)^(1/12)
smm_to_cpr <- function(smm) 1 - (1 - smm)^12

# A 10% CPR
cpr_to_smm(0.10)        # 0.00874
# A 1% monthly SMM
smm_to_cpr(0.01)        # 0.1136


## ---- 02: Continuous-Hazard Conversions  (qmd line 250) -------------------------------

hazard_to_smm <- function(h, dt = 1/12) 1 - exp(-h * dt)
smm_to_hazard <- function(smm, dt = 1/12) -log(1 - smm) / dt

# 12% annualized hazard
hazard_to_smm(0.12)     # 0.00995


## ---- 03: PSA Curve  (qmd line 260) ---------------------------------------------------

psa_curve <- function(month, multiplier = 1) {
  base <- pmin(0.06, 0.002 * month)
  base * multiplier
}

library(ggplot2)
months <- 1:360
ggplot(data.frame(month = months, cpr = psa_curve(months, 1.5) * 100),
       aes(month, cpr)) +
  geom_line() +
  labs(x = "Month", y = "Annualized CPR (%)", title = "150 PSA") +
  theme_minimal()


## ---- 04: Empirical Seasoning Curve for Amortizing Loans  (qmd line 281) --------------

library(survival)
library(survminer)
library(dplyr)

# One row per loan: loan_age in months at exit, prepay_event flag
loan_panel <- read.csv("data/sample_loan_panel.csv")
km_fit <- survfit(Surv(loan_age, prepay_event) ~ 1, data = loan_panel)
ggsurvplot(km_fit, fun = "event", conf.int = TRUE,
           legend = "none",
           xlab = "Loan age (months)",
           ylab = "Cumulative prepay incidence")

# Smoothed monthly hazard estimate
hazards <- with(loan_panel,
                tapply(prepay_event, loan_age, mean, na.rm = TRUE))
smm_curve <- data.frame(age = as.numeric(names(hazards)),
                        smm = hazards)


